//! The embedded subset of Junction's operation catalogue that check packs call.
//!
//! `data/catalog.json` is generated by `scripts/check-catalog.py` from
//! `data/operations.txt`; `data/risk-overrides.toml` holds reviewed risk
//! corrections applied through the registry's operator override mechanism.
use anyhow::{Context, Result};
use junction_core::cloud::{CloudEndpoints, CloudService};
use junction_core::{JunctionOperation, RegistryManifest};
use junction_registry::Registry;
use std::collections::BTreeMap;
use std::sync::OnceLock;

const CATALOG: &str = include_str!("../data/catalog.json");
const OPERATIONS: &str = include_str!("../data/operations.txt");
const RISK_OVERRIDES: &str = include_str!("../data/risk-overrides.toml");

pub fn manifest() -> &'static RegistryManifest {
    static MANIFEST: OnceLock<RegistryManifest> = OnceLock::new();
    MANIFEST.get_or_init(|| serde_json::from_str(CATALOG).expect("embedded check catalogue parses"))
}

/// A fresh registry with the reviewed risk overrides applied.
pub fn registry() -> Result<Registry> {
    Registry::load(manifest().clone())
        .context("loading embedded check catalogue")?
        .with_risk_overrides(junction_registry::overrides::RiskOverrides::parse(
            RISK_OVERRIDES,
        )?)
        .context("applying check catalogue risk overrides")
}

/// Every version of `id` in the embedded catalogue, stable first.
pub fn versions(id: &str) -> Vec<&'static JunctionOperation> {
    let mut found: Vec<_> = manifest()
        .operations
        .iter()
        .filter(|o| o.id == id)
        .collect();
    found.sort_by_key(|o| o.preview);
    found
}

pub fn contains(id: &str) -> bool {
    manifest().operations.iter().any(|o| o.id == id)
}

/// Only a Graph beta (preview) version is embedded, so calls must allow preview.
pub fn preview_only(id: &str) -> bool {
    let v = versions(id);
    !v.is_empty() && v.iter().all(|o| o.preview)
}

/// Entries of `data/operations.txt` (`id` or `id@beta`).
pub fn listed() -> Vec<(String, bool)> {
    OPERATIONS
        .lines()
        .map(str::trim)
        .filter(|l| !l.is_empty() && !l.starts_with('#'))
        .map(|l| match l.split_once('@') {
            Some((id, _)) => (id.to_owned(), true),
            None => (l.to_owned(), false),
        })
        .collect()
}

/// Where an operation is sent and which token audience it needs, for one cloud.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Route {
    pub service: CloudService,
    pub endpoint: String,
    pub audience: String,
}

/// The service an operation belongs to. Defender for Endpoint operations are
/// served from the Defender XDR host but take a Defender for Endpoint token.
fn services(operation: &JunctionOperation) -> (CloudService, CloudService) {
    let id = operation.id.as_str();
    if id.starts_with("defender.endpoint.") {
        (CloudService::DefenderXdr, CloudService::DefenderEndpoint)
    } else if id.starts_with("defender.xdr.") {
        (CloudService::DefenderXdr, CloudService::DefenderXdr)
    } else if id.starts_with("graph.") {
        (CloudService::Graph, CloudService::Graph)
    } else if id.starts_with("azure.log_analytics_query.") {
        (CloudService::LogAnalytics, CloudService::LogAnalytics)
    } else {
        (CloudService::Arm, CloudService::Arm)
    }
}

pub fn route(operation: &JunctionOperation, endpoints: &CloudEndpoints) -> Result<Route> {
    let (host, token) = services(operation);
    let upstream = match &operation.endpoint_template {
        // Bind variables that have exactly one documented choice (such as the
        // Log Analytics `apiVersion`); everything else keeps its default.
        Some(template) => {
            let bindings: BTreeMap<String, String> = template
                .variables
                .iter()
                .filter(|(_, v)| v.default.is_none())
                .filter_map(|(name, v)| match v.choices.as_deref() {
                    Some([only]) => Some((name.clone(), only.clone())),
                    _ => None,
                })
                .collect();
            template.resolve(&bindings)?
        }
        None => operation.base_url.clone(),
    };
    let target = endpoints.resolve(host, &upstream)?;
    let audience = endpoints
        .target(token)?
        .audience
        .clone()
        .context("service audience requires explicit configuration")?;
    Ok(Route {
        service: token,
        endpoint: target.endpoint,
        audience,
    })
}

/// Host label used for per-host concurrency limits.
pub fn host_key(id: &str) -> String {
    versions(id)
        .first()
        .map(|o| format!("{:?}", services(o).0))
        .unwrap_or_else(|| "other".into())
}

/// Imported application permission requirements for an operation, if the
/// catalogue has them (Graph and Defender publish them; ARM uses RBAC).
pub fn required_permissions(id: &str) -> Vec<String> {
    let mut out: Vec<String> = versions(id)
        .first()
        .and_then(|o| o.required_permissions())
        .unwrap_or_default()
        .into_iter()
        .flatten()
        .collect();
    out.sort();
    out.dedup();
    out
}

#[cfg(test)]
mod tests {
    use super::*;
    use junction_core::cloud::MicrosoftCloud;

    #[test]
    fn catalogue_matches_operation_list() {
        let mut wanted: Vec<(String, bool)> = listed();
        wanted.sort();
        let mut embedded: Vec<(String, bool)> = manifest()
            .operations
            .iter()
            .map(|o| (o.id.clone(), o.preview))
            .collect();
        embedded.sort();
        assert_eq!(
            embedded, wanted,
            "run scripts/check-catalog.py after editing data/operations.txt"
        );
        registry().expect("catalogue and overrides load");
    }

    #[test]
    fn every_operation_routes_in_the_public_cloud() {
        let endpoints = MicrosoftCloud::Public.endpoints().unwrap();
        for op in &manifest().operations {
            let route = route(op, &endpoints).unwrap_or_else(|e| panic!("{}: {e}", op.id));
            assert!(route.endpoint.starts_with("https://"), "{}", op.id);
        }
        let mde = versions("defender.endpoint.machines.list")[0];
        let r = route(mde, &endpoints).unwrap();
        assert_eq!(r.audience, "https://api.securitycenter.microsoft.com");
        assert!(r.endpoint.starts_with("https://api.security.microsoft.com"));
        let la = versions("azure.log_analytics_query.query.execute")[0];
        assert_eq!(
            route(la, &endpoints).unwrap().endpoint,
            "https://api.loganalytics.io/v1"
        );
    }

    #[test]
    fn read_only_policy_allows_every_embedded_operation() {
        let registry = registry().unwrap();
        let policy = junction_policy::Policy::default();
        for (id, preview) in listed() {
            let op = registry.resolve(&id, None, preview).unwrap();
            assert_eq!(
                policy.authorize_operation(op, "tenant"),
                junction_policy::Decision::Allowed,
                "{id}"
            );
        }
    }
}
